{
  "name": "SR830 锁相放大器",
  "name_en": "SR830 Lock-in Amplifier",
  "manufacturer": "Stanford Research Systems",
  "description": "用于相敏检测的数字锁相放大器。该设备可提供内部参考正弦输出，配置输入模式、灵敏度、时间常数、滤波与储存参数，并读取测量值、辅助模拟量和缓冲区数据，常用于弱信号与噪声环境下的精密测量。",
  "description_en": "A digital lock-in amplifier for phase-sensitive detection. It can provide an internal sine reference, configure input mode, sensitivity, time constant, filtering, and storage settings, and read measured values, auxiliary analog signals, and buffered data for precision weak-signal measurements in noisy experiments.",
  "tag_hints": [
    "lock-in amplifier",
    "phase-sensitive detection",
    "weak signal measurement",
    "harmonic detection",
    "aux analog I/O",
    "buffered acquisition",
    "SRS SR830"
  ],
  "actions": [
    {
      "action_name": "auto-auto_gain_async_async",
      "description": "异步启动自动增益调整。",
      "description_en": "Asynchronously start automatic gain adjustment."
    },
    {
      "action_name": "auto-auto_offset_async_async",
      "description": "异步启动自动偏置调整。",
      "description_en": "Asynchronously start automatic offset adjustment."
    },
    {
      "action_name": "auto-auto_phase_async_async",
      "description": "异步启动自动相位调整。",
      "description_en": "Asynchronously start automatic phase adjustment."
    },
    {
      "action_name": "auto-auto_reserve_async_async",
      "description": "异步启动自动储备模式调整。",
      "description_en": "Asynchronously start automatic reserve-mode adjustment."
    },
    {
      "action_name": "auto-measure_async",
      "description": "异步读取测量量。",
      "description_en": "Asynchronously read measured quantities."
    },
    {
      "action_name": "auto-pause_data_storage_async",
      "description": "异步暂停数据存储。",
      "description_en": "Asynchronously pause data storage."
    },
    {
      "action_name": "auto-read_buffer_async",
      "description": "异步读取缓冲区数据。",
      "description_en": "Asynchronously read buffered data."
    },
    {
      "action_name": "auto-recall_state_async",
      "description": "异步调用已保存的仪器状态。",
      "description_en": "Asynchronously recall a saved instrument state."
    },
    {
      "action_name": "auto-reset_data_storage_async",
      "description": "异步重置数据存储。",
      "description_en": "Asynchronously reset data storage."
    },
    {
      "action_name": "auto-save_state_async",
      "description": "异步保存仪器状态。",
      "description_en": "Asynchronously save the instrument state."
    },
    {
      "action_name": "auto-start_data_storage_async",
      "description": "异步启动数据存储。",
      "description_en": "Asynchronously start data storage."
    },
    {
      "action_name": "auto-trigger_async",
      "description": "异步发送触发命令。",
      "description_en": "Asynchronously send a trigger command."
    },
    {
      "action_name": "auto-reference_phase_shift",
      "description": "获取或设置参考相位偏移。",
      "description_en": "Get or set the reference phase shift."
    },
    {
      "action_name": "auto-reference_internal",
      "description": "获取或设置是否使用内部参考源。",
      "description_en": "Get or set whether the internal reference source is used."
    },
    {
      "action_name": "auto-frequency",
      "description": "获取或设置参考频率。",
      "description_en": "Get or set the reference frequency."
    },
    {
      "action_name": "auto-reference_trigger",
      "description": "获取或设置参考触发模式。",
      "description_en": "Get or set the reference trigger mode."
    },
    {
      "action_name": "auto-harmonic",
      "description": "获取或设置谐波检测阶数。",
      "description_en": "Get or set the harmonic detection number."
    },
    {
      "action_name": "auto-sine_output_amplitude",
      "description": "获取或设置内部正弦输出幅度。",
      "description_en": "Get or set the internal sine output amplitude."
    },
    {
      "action_name": "auto-input_configuration",
      "description": "获取或设置输入配置。",
      "description_en": "Get or set the input configuration."
    },
    {
      "action_name": "auto-input_shield",
      "description": "获取或设置输入屏蔽方式。",
      "description_en": "Get or set the input shield mode."
    },
    {
      "action_name": "auto-input_coupling",
      "description": "获取或设置输入耦合方式。",
      "description_en": "Get or set the input coupling mode."
    },
    {
      "action_name": "auto-input_filter",
      "description": "获取或设置输入滤波选项。",
      "description_en": "Get or set the input filter option."
    },
    {
      "action_name": "auto-sensitivity",
      "description": "获取或设置测量灵敏度。",
      "description_en": "Get or set the measurement sensitivity."
    },
    {
      "action_name": "auto-reserve_mode",
      "description": "获取或设置储备模式。",
      "description_en": "Get or set the reserve mode."
    },
    {
      "action_name": "auto-time_constants",
      "description": "获取或设置时间常数。",
      "description_en": "Get or set the time constant."
    },
    {
      "action_name": "auto-filter_db_per_oct",
      "description": "获取或设置低通滤波器滚降斜率。",
      "description_en": "Get or set the low-pass filter roll-off."
    },
    {
      "action_name": "auto-sync_filter",
      "description": "获取或设置同步滤波功能。",
      "description_en": "Get or set the synchronous filter setting."
    },
    {
      "action_name": "auto-display",
      "description": "获取或设置显示通道内容。",
      "description_en": "Get or set the display channel content."
    },
    {
      "action_name": "auto-front_output",
      "description": "获取或设置前面板输出内容。",
      "description_en": "Get or set the front-panel output assignment."
    },
    {
      "action_name": "auto-analog_input",
      "description": "读取辅助模拟输入通道。",
      "description_en": "Read an auxiliary analog input channel."
    },
    {
      "action_name": "auto-analog_output",
      "description": "获取或设置辅助模拟输出通道。",
      "description_en": "Get or set an auxiliary analog output channel."
    },
    {
      "action_name": "auto-remote",
      "description": "获取或设置远程控制状态。",
      "description_en": "Get or set the remote-control state."
    },
    {
      "action_name": "auto-key_click_enabled",
      "description": "获取或设置按键提示音开关。",
      "description_en": "Get or set whether key click is enabled."
    },
    {
      "action_name": "auto-alarm_enabled",
      "description": "获取或设置报警功能开关。",
      "description_en": "Get or set whether the alarm is enabled."
    },
    {
      "action_name": "auto-recall_state",
      "description": "调用已保存的仪器状态。",
      "description_en": "Recall a saved instrument state."
    },
    {
      "action_name": "auto-save_state",
      "description": "保存当前仪器状态。",
      "description_en": "Save the current instrument state."
    },
    {
      "action_name": "auto-wait_bit1",
      "description": "等待状态位 1 满足条件。",
      "description_en": "Wait for status bit 1 to meet its condition."
    },
    {
